    "record_types": {
      "A":    { "name": "A — IPv4 Address",      "desc": "Maps a hostname to a 32-bit IPv4 address. The most fundamental DNS record — what your browser resolves when you type a domain name." },
      "AAAA": { "name": "AAAA — IPv6 Address",   "desc": "Maps a hostname to a 128-bit IPv6 address. Same role as an A record but for IPv6. Both A and AAAA can coexist for dual-stack hosts." },
      "CNAME":{ "name": "CNAME — Canonical Name","desc": "Alias from one hostname to another. The resolver follows the chain until it reaches an A/AAAA record. Cannot coexist with other record types at the same name (apex restriction)." },
      "MX":   { "name": "MX — Mail Exchange",    "desc": "Specifies the mail server responsible for accepting SMTP email for the domain. Includes a priority value — lower wins. Multiple MX records provide redundancy." },
      "NS":   { "name": "NS — Name Server",      "desc": "Delegates authority for a DNS zone to specific name servers. NS records at the zone apex identify which servers are authoritative for that domain." },
      "PTR":  { "name": "PTR — Pointer (Reverse)","desc": "Reverse DNS lookup — maps an IP address back to a hostname. Lives under in-addr.arpa (IPv4) or ip6.arpa (IPv6). Used by mail servers to verify sender identity." },
      "SOA":  { "name": "SOA — Start of Authority","desc": "Administrative record for the zone: primary nameserver, responsible party email, serial number (for zone transfers), and refresh/retry/expire/TTL timers. Every zone has exactly one SOA." },
      "SRV":  { "name": "SRV — Service Locator", "desc": "Specifies host, port, priority, and weight for a specific service (e.g. _sip._tcp, _xmpp-client._tcp). Allows a domain to advertise service endpoints without hardcoding IPs." },
      "TXT":  { "name": "TXT — Text",            "desc": "Stores arbitrary text data. Widely used for SPF (email sender policy), DKIM public keys, DMARC policy, domain ownership verification, and ACME DNS-01 challenge responses." },
      "CAA":  { "name": "CAA — CA Authorization", "desc": "Specifies which Certificate Authorities are permitted to issue TLS certificates for the domain. Prevents misissued certificates. Checked by CAs before signing — not enforced by browsers directly." }
    },
