    "about_body": "iperf is an active measurement tool for the maximum achievable bandwidth on IP networks. One host runs as a server (listener) and another connects as a client to push (or pull) traffic over TCP, UDP or SCTP, reporting throughput, jitter and packet loss. iperf3 (binary iperf3) is a modern rewrite with JSON output and reverse/bidirectional modes; iperf2 (binary iperf) is multi-client and stronger for Wi-Fi and multicast. The two are NOT wire-compatible — both ends must run the same version.",
