    "docker_run_label": "docker run (iperf3)",
    "docker_compose_label": "docker compose",
    "docker_compose_hint": "Save as docker-compose.yml, then run docker compose up -d.",
    "notes_heading": "Important Notes",
    "note_1": "iperf3 handles only one client at a time; run multiple iperf3 instances on different ports for concurrent tests.",
    "note_2": "Control and data traffic both use the same port (default 5201 for iperf3, 5001 for iperf2) — open both TCP and UDP on that port in your firewall.",
    "note_3": "UDP tests require explicit -b bandwidth target; without it iperf2 defaults to 1 Mbit/s and iperf3 defaults to 1 Mbit/s as well.",
    "note_4": "iperf2 and iperf3 are NOT wire-compatible — client and server must run the same major version.",
    "note_5": "For high-BDP (long fat network) paths, increase the socket window with -w (e.g. -w 4M) and use -P multiple streams to saturate the link.",
