    "explanation_iptables_filter": "iptables uses the 'filter' table by default. 'INPUT' handles packets destined for the local system, while 'FORWARD' handles traffic passing through (routing). Stateful rules (using conntrack) are recommended for security.",
    "explanation_masquerade": "Masquerading is a form of Dynamic SNAT. It replaces the source IP with the IP of the outgoing interface ({iface}). It's used to give a private LAN access to the internet via a dynamic public IP.",
    "explanation_snat": "Static SNAT (Source NAT) replaces the source IP with a fixed address ({target}). Used when the gateway has multiple static IPs.",
    "explanation_dnat": "DNAT (Destination NAT) or Port Forwarding modifies the destination IP/port of incoming packets. This allows external users to access a server inside your private network.",
    "explanation_nftables": "nftables is the modern replacement for iptables. It uses a single 'nft' tool and supports 'inet' tables that handle both IPv4 and IPv6. NAT rules are added as hooks to the 'nat' table, usually with priority -100 for prerouting and 100 for postrouting.",
    "explanation_default": "This configuration generates the necessary syntax for the selected platform. Most firewall policies follow a top-down execution order.",
    "explanation_ios": "IOS/IOS-XE ACLs are applied to interfaces using \"ip access-group NAME in|out\". Named ACLs (ip access-list extended) are preferred over numbered — they support adding/deleting individual entries without replacing the whole list. \"log\" adds CPU overhead on the router; use sparingly in production.",
    "explanation_nxos": "NX-OS only supports named ACLs (no numbered). Sequence numbers allow you to insert rules between existing entries. The \"feature nat\" command enables NAT — verify your license tier supports it (N5K/N7K require specific feature sets).",
    "explanation_xr": "IOS-XR uses \"ipv4 access-list\" (not \"ip\") and \"ingress\"/\"egress\" (not \"in\"/\"out\"). All configuration is staged in candidate config and only takes effect after \"commit\". Use \"rollback configuration last 1\" to undo.",
    "explanation_asa": "ASA ACLs are stateful (the state table handles return traffic). ACL entries are processed top-down with an implicit deny at the end. Object groups reduce ACL size significantly for repeated address/service patterns.",
    "explanation_junos": "JunOS firewall filters are stateless. Apply \"input\" for ingress (arriving) and \"output\" for egress (leaving) traffic on the interface unit. Add \"count COUNTER_NAME\" in the then block for per-term hit counting. Commit with \"commit confirmed 5\" for a 5-minute auto-rollback safety window.",
    "explanation_panos": "PAN-OS uses App-ID (not raw L4 protocols) in the \"application\" field. Service objects define L4 protocol+port. Security rules are evaluated top-down. Use \"application any / service any\" when migrating from port-based firewalls, then incrementally tighten with App-ID.",
    "explanation_fortigate": "FortiGate policies are directional: srcintf/dstintf define traffic flow. Implicit deny is at the bottom. logtraffic \"all\" logs both permitted and denied sessions — use \"utm\" for permit-only to reduce volume. IP pools define SNAT translation addresses.",
    "explanation_checkpoint": "Check Point enforces policy from the Security Management Server. Rules are compiled and pushed to gateways after \"publish\" + \"install-policy\". The mgmt_cli tool requires an active session token. Policy changes are atomic — partial installs are not possible.",
    "explanation_pfsense": "pfSense/OPNsense rules are processed top-down per interface. The first matching rule wins (pass or block). Floating rules can match across all interfaces. Outbound NAT in Hybrid mode allows manual rules while keeping auto-generated ones for other traffic.",
    "explanation_pf": "OpenBSD pf processes rules top-to-bottom but the last matching rule wins by default (use \"quick\" to stop at first match). Tables are efficient for large address sets. The \"keep state\" keyword enables stateful connection tracking.",
    "explanation_aws_sg": "Security Groups are stateful — return traffic is automatically allowed. NACLs are stateless and require explicit allow rules for both inbound and outbound, including ephemeral ports (1024-65535) for return TCP traffic. Lower NACL rule numbers have higher priority.",
    "explanation_azure_nsg": "Azure NSGs are stateful and evaluated by priority (lower number = first match). They apply at the NIC or subnet level. Use Service Tags (e.g., \"Internet\", \"VirtualNetwork\", \"AzureLoadBalancer\") to match Azure service ranges without managing IPs.",
    "explanation_gcp": "GCP VPC firewall rules are stateful. ALLOW and DENY rules are evaluated separately — DENY rules with lower priority numbers win over ALLOW. Rules apply to all instances in the network unless target tags or service accounts are specified.",
    "explanation_mikrotik": "MikroTik processes filter rules top-to-bottom; the first matching rule applies. Use the \"forward\" chain for routed traffic, \"input\" for traffic destined to the router itself. Address-list groups simplify management for many source prefixes.",
    "explanation_vyos": "VyOS uses named rule sets applied to interfaces. Rules are evaluated by rule number (ascending). All config is staged and applied only after \"commit\". \"save\" writes to the persistent config — without it, changes are lost on reboot.",
    "explanation_openwrt": "OpenWrt firewall uses a zone-based model on top of iptables. UCI rules translate to iptables rules at runtime. For advanced NAT, /etc/firewall.user provides a persistent hook for raw iptables commands that run at firewall init.",
    "explanation_windows": "Windows Defender Firewall rules are stateful. netsh advfirewall and PowerShell New-NetFirewallRule produce equivalent rules. Rules are evaluated by priority with \"block\" taking precedence over \"allow\" by default for the same port/protocol.",
    "explanation_ufw": "UFW (Uncomplicated Firewall) is a frontend for iptables. Rules are evaluated in order — insert at position 1 for highest priority. UFW does not directly manage the NAT table; edit /etc/ufw/before.rules for POSTROUTING/PREROUTING rules.",
    "platform_cisco_ios": "Cisco IOS / IOS-XE",
