    "swap_desc": "Replaces the top label with a new outgoing label and forwards the packet.",
    "pop_desc": "Removes the top label. PHP (Penultimate Hop Popping) pops one hop before egress.",
    "php_desc": "Last LSR before egress pops the transport label, reducing egress LER work. Implicit-null label (3) signals PHP.",
