    "title": "SSH Config Generator",
    "subtitle": "~/.ssh/config lets you replace long ssh commands with a simple alias — ssh core-rtr-01 instead of ssh -i ~/.ssh/id_ed25519 -l admin -o ServerAliveInterval=60 10.0.0.1. This tool builds those entries for you, with vendor presets, jump hosts, tunnels, and per-host overrides.",
