    "metric_loss_response": "Loss Response",
    "strat_reno": "Additive Increase / Multiplicative Decrease (AIMD)",
    "strat_cubic": "Cubic function — aggressive on high-BDP networks",
    "strat_bbr": "Model-based — estimates bandwidth & RTT",
    "loss_resp_reno": "cwnd halved on loss; timeout resets to 1 MSS",
    "loss_resp_cubic": "cwnd *= 0.7; concave-convex recovery via W(t) = C(t-K)^3 + Wmax",
    "loss_resp_bbr": "Ignores loss; continues at estimated BDP rate",
    "loss_impact_title": "Loss Impact Analysis",
    "loss_impact_hint": "At the configured loss rate, each algorithm responds differently. BBR is loss-tolerant by design.",
    "recovery_reno": "AIMD: halve cwnd, linear regrowth",
    "recovery_cubic": "Faster recovery via cubic function",
    "recovery_bbr": "No recovery needed (loss-tolerant)",
    "notes_reno": "Conservative; slowest to recover on high-BDP paths",
    "notes_cubic": "Better on LFNs; default in Linux since kernel 2.6.19",
    "notes_bbr": "Best throughput under loss; may cause queuing if not tuned",
    "phase_slow_start": "Slow Start",
    "phase_ca": "Congestion Avoidance",
    "phase_fast_recovery": "Fast Recovery",
    "sysctl_title": "Linux TCP Tuning (sysctl)",
    "sysctl_subtitle": "Generate sysctl commands to tune Linux TCP buffers and congestion control for your path parameters.",
    "sysctl_algo": "Congestion Control Algorithm",
    "sysctl_apply_hint": "Apply with: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Values are calculated from your BDP.",
    "ref_title": "Algorithm Reference",
    "ref_reno_desc": "Classic AIMD algorithm. Slow start doubles cwnd each RTT until ssthresh. Congestion avoidance adds ~1 segment per RTT. On 3 duplicate ACKs: ssthresh = cwnd/2, cwnd = ssthresh. On timeout: cwnd = 1 MSS. Fair but under-utilizes high-BDP paths after loss.",
    "ref_cubic_desc": "Default in Linux. Uses a cubic function W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7). After loss, cwnd drops to 70% of W_max, then grows via the concave-convex curve. More aggressive than Reno on long-fat networks. K = (W_max * 0.3 / C)^(1/3).",
    "ref_bbr_desc": "Google's model-based algorithm. Estimates bottleneck bandwidth and min RTT instead of using loss as a signal. Phases: Startup (2.89x gain), Drain, ProbeBW (8-phase gain cycle: 1.25/0.75/1...), ProbeRTT (4 segments every ~10s). Achieves full throughput even with loss.",
    "phase_startup": "Startup",
    "phase_drain": "Drain",
    "phase_probe_bw": "ProbeBW",
    "phase_probe_rtt": "ProbeRTT",
