    "explanation_title": "Understanding NAT vs. PAT",
    "explanation_intro": "Network Address Translation (NAT) and Port Address Translation (PAT) are techniques to map one IP address space to another, primarily used to preserve limited public IPv4 addresses or resolve subnet conflicts.",
    "nat_expl_title": "1. What is NAT?",
    "nat_expl_desc": "NAT translates IP addresses on a 1-to-1 basis. It can be Static (permanent mapping of one private IP to one public IP, ideal for public-facing servers) or Dynamic (allocates a public IP from a pool to a private host on-demand. Once all public IPs are assigned, subsequent hosts are blocked until an IP is freed). Port numbers are unmodified.",
    "pat_expl_title": "2. What is PAT (NAT Overload)?",
    "pat_expl_desc": "PAT (or Port Address Translation / NAT Overload) translates both the IP address and the source port number on a many-to-one (N-to-1) basis. Multiple private hosts share a single public IP address by assigning unique source ports (e.g. 192.168.1.10:5000 and 192.168.1.11:5000 map to 203.0.113.10:1024 and 203.0.113.10:1025). This is the standard method for home routers and enterprise internet access.",
    "comparison_table_title": "Comparison Summary",
    "comp_header_feature": "Feature",
    "comp_header_nat": "NAT (1-to-1)",
    "comp_header_pat": "PAT (N-to-1 / Overload)",
