    "comp_row_limit_pat": "Up to ~64,500 sessions per public IP",
    "comp_row_use": "Primary Use Case",
    "comp_row_use_nat": "Publishing servers, DMZ, outbound without overload",
    "comp_row_use_pat": "Standard LAN Internet access (conserve IPs)"
